Here's a sample Kotlin implementation for battery-efficient location monitoring in crisis scenarios. This implementation includes geofencing using ScreenOrientationEventListener to trigger GPS pings when device rotation suggests movement, foreground service persistence through orientation changes, periodic coordinate logging to Firebase with WorkManager's expedited constraints, and maintaining location collection during Doze mode using FLAG_IGNORE_BATTERY_OPTIMIZATIONS.

```kotlin
// Create a Geofencing client
private lateinit var geofencingClient: GeofencingClient

// Create a ScreenOrientationEventListener
private lateinit var orientationEventListener: ScreenOrientationEventListener

// Create a WorkManager instance
private lateinit var workManager: WorkManager

fun startLocationMonitoring() {
    // Initialize the Geofencing client
    geofencingClient = LocationServices.getGeofencingClient(this)

    // Initialize the ScreenOrientationEventListener
    orientationEventListener = object : ScreenOrientationEventListener(this) {
        override fun onOrientationChanged(orientation: Int) {
            // Trigger GPS pings when device rotation suggests movement
            // Implement GPS pinging logic here
        }
    }

    // Register the ScreenOrientationEventListener
    orientationEventListener.enable()

    // Initialize the WorkManager
    workManager = WorkManager.getInstance(this)

    // Create a periodic WorkRequest for coordinate logging to Firebase
    val periodicWorkRequest = PeriodicWorkRequestBuilder<LocationWorker>(15, TimeUnit.MINUTES)
        .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
        .addTag("network_latency_diagnostics")
        .build()

    // Enqueue the periodic WorkRequest
    workManager.enqueueUniquePeriodicWork("locationLogging", ExistingPeriodicWorkPolicy.KEEP, periodicWorkRequest)

    // Request foreground service permission
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
        if (ContextCompat.checkSelfPermission(this, Manifest.permission.FOREGROUND_SERVICE) != PackageManager.PERMISSION_GRANTED) {
            // Request foreground service permission
            ActivityCompat.requestPermissions(this, arrayOf(Manifest.permission.FOREGROUND_SERVICE), 0)
        }
    }

    // Request background permission programmatically
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
        if (ContextCompat.checkSelfPermission(this, Manifest.permission.ACCESS_BACKGROUND_LOCATION) != PackageManager.PERMISSION_GRANTED) {
            if (ActivityCompat.shouldShowRequestPermissionRationale(this, Manifest.permission.ACCESS_BACKGROUND_LOCATION)) {
                // Explain the need for background location permission to the user
            } else {
                // Request background location permission
                ActivityCompat.requestPermissions(this, arrayOf(Manifest.permission.ACCESS_BACKGROUND_LOCATION), 1)
            }
        }
    }

    // Maintain location collection during Doze mode using FLAG_IGNORE_BATTERY_OPTIMIZATIONS
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
        val packageName = applicationContext.packageName
        val pm = getSystemService(Context.POWER_SERVICE) as PowerManager
        if (!pm.isIgnoringBatteryOptimizations(packageName)) {
            // Request ignore battery optimizations
            val intent = Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS)
            intent.data = Uri.parse("package:$packageName")
            startActivity(intent)
        }
    }
}

class LocationWorker(context: Context, params: WorkerParameters) : Worker(context, params) {
    override fun doWork(): Result {
        // Implement coordinate logging to Firebase here
        return Result.success()
    }
}

override fun onDestroy() {
    super.onDestroy()
    // Unregister the ScreenOrientationEventListener
    orientationEventListener.disable()
}
```

This Kotlin implementation demonstrates how to achieve battery-efficient location monitoring in crisis scenarios by utilizing geofencing, foreground service persistence, periodic coordinate logging, and maintaining location collection during Doze mode while complying with FEMA guidelines.
